return {
    [" 打开证词记录，查看调查中获得的所有陈述。"] = " Открыть протокол показаний и просмотреть все свидетельства, собранные в ходе расследования.",
    [" 混乱之力"] = "Сила Хаоса",
    [" 露米代行"] = "Люмианский прокси",
    ["一本来历不明的日记，记录着贝克兰德近期发生的失忆事件。"] = "Дневник неизвестного происхождения, в котором записаны недавние случаи потери памяти в Бэкланде.",
    ["七次连击，每次命中恢复自身生命。"] = "Серия из семи ударов, каждое попадание восстанавливает себе здоровье.",
    ["三波灵界轰击分别造成<HighLight>108.25%/108.25%/216.5%</>攻击伤害。第二波施加重伤灼烧：目标每秒受到其自身<HighLight>1%</>最大生命伤害，受治疗效果降低<HighLight>33%</>，持续<HighLight>4</>秒。"] = "Три волны обстрела Миром Духов наносят <HighLight>108.25%/108.25%/216.5%</> урона от атаки соответственно. Вторая волна накладывает Жгучую рану: цель каждую секунду получает урон в размере <HighLight>1%</> своего максимального здоровья, а получаемое лечение снижается на <HighLight>33%</> на <HighLight>4</> сек.",
    ["三波灵界轰击分别造成<HighLight>750%/750%/1500%</>攻击伤害。第二波施加重伤灼烧：目标每秒受到其自身<HighLight>1%</>最大生命伤害，受治疗效果降低<HighLight>33%</>，持续<HighLight>4</>秒。"] = "Три волны бомбардировки Мира Духов наносят <HighLight>750%/750%/1500%</> урона от атаки соответственно. Вторая волна накладывает тяжёлое ранение и ожог: цель каждую секунду получает урон в размере <HighLight>1%</> своего максимального здоровья, получаемое лечение снижается на <HighLight>33%</>, длительность — <HighLight>4</> сек.",
    ["三波灵界轰击，第二波施加重伤灼烧。"] = "Три волны обстрела Миром Духов, вторая волна накладывает Жгучую рану.",
    ["三环AOE"] = "Трехкольцевое AOE",
    ["三连飞弹"] = "Тройной снаряд",
    ["世界的指导"] = "Наставление Мира",
    ["丧钟"] = "Похоронный Звон",
    ["丰饶圣痕"] = "Священная печать изобилия",
    ["丰饶灾变"] = "Бедствие изобилия",
    ["亡者之花"] = "Цветок Мертвых",
    ["令血玫在周身绽放，伤害附近敌人。"] = "Заставляет кровавые розы расцвести вокруг себя, нанося урон находящимся поблизости врагам.",
    ["以巨龙威压横扫前方，造成{*d,F1690001,atkMin,2}点攻击伤害，并施加<HighLight>4</>秒重伤灼烧：每秒损失{*d,F1690001,maxHp,0.01}点生命，受治疗效果降低<HighLight>33%</>。同时为生命最低的<HighLight>2</>名友军各恢复{*d,F1690001,maxHp,0.1}点生命。三星时：以巨龙威压横扫前方，造成{*d,F1690001,atkMin,4.6}点攻击伤害，并施加<HighLight>4</>秒重伤灼烧：每秒损失{*d,F1690001,maxHp,0.01}点生命，受治疗效果降低<HighLight>33%</>。同时为生命最低的<HighLight>2</>名友军各恢复{*d,F1690001,maxHp,0.1}点生命。"] = "Обрушивает мощь дракона на противников впереди, нанося {*d,F1690001,atkMin,2} ед. урона от атаки и накладывая на <HighLight>4</> сек. эффект «Тяжёлое ранение и ожог»: теряет {*d,F1690001,maxHp,0.01} ед. здоровья в секунду, получаемое лечение снижено на <HighLight>33%</>. Также восстанавливает по {*d,F1690001,maxHp,0.1} ед. здоровья <HighLight>2</> союзникам с наименьшим здоровьем. При 3 звёздах: обрушивает мощь дракона на противников впереди, нанося {*d,F1690001,atkMin,4.6} ед. урона от атаки и накладывая на <HighLight>4</> сек. эффект «Тяжёлое ранение и ожог»: теряет {*d,F1690001,maxHp,0.01} ед. здоровья в секунду, получаемое лечение снижено на <HighLight>33%</>. Также восстанавливает по {*d,F1690001,maxHp,0.1} ед. здоровья <HighLight>2</> союзникам с наименьшим здоровьем.",
    ["以怒意发动连斩，共造成{*d,F1690001,atkMin,5.75}点攻击伤害，随后获得{*d,F1690001,maxHp,0.12}点护盾，持续<HighLight>4</>秒。"] = "В ярости наносит серию рассекающих ударов, в сумме {*d,F1690001,atkMin,5.75} ед. урона от атаки, затем получает щит на {*d,F1690001,maxHp,0.12} ед. на <HighLight>4</> сек.",
    ["以死灵印记重创当前目标。"] = "Наносит тяжелый удар по текущей цели некромантской печатью.",
    ["以灵性凝聚铠甲覆盖全身，获得吸收伤害的护盾，在护盾被击破时持续霸体。"] = "Концентрирует духовность, покрывая тело доспехом, который поглощает урон в виде щита, а при разрушении щита сохраняет Суперброню.",
    ["以知识辉耀对敌方全体造成{*d,F1690001,atkMin,2.7}点攻击伤害。随后随机获得<HighLight>25%</>攻击，持续<HighLight>6</>秒，或立即恢复<HighLight>45</>点法力。"] = "Сиянием знания наносит всем врагам {*d,F1690001,atkMin,2.7} ед. урона от атаки. Затем случайно получает <HighLight>25%</> атаки на <HighLight>6</> сек. или сразу восстанавливает <HighLight>45</> ед. маны.",
    ["以藤蔓攻击当前目标。"] = "Атакует текущую цель лозами.",
    ["以蛛肢绞杀前方敌人，造成{*d,F1690001,atkMin,2}点攻击伤害。施法时恢复自身<HighLight>20%</>最大生命，防御提高<HighLight>30</>点，持续<HighLight>4</>秒。"] = "Душит врагов впереди паучьими лапами, нанося {*d,F1690001,atkMin,2} ед. урона от атаки. При применении восстанавливает <HighLight>20%</> макс. здоровья и повышает защиту на <HighLight>30</> на <HighLight>4</> сек.",
    ["以血焰横扫自身周围<HighLight>1</>格内的全部敌人，造成<HighLight>288%</>攻击伤害。自身攻速提高<HighLight>30%</>，持续<HighLight>4</>秒。"] = "Кровавым пламенем поражает всех врагов в радиусе <HighLight>1</> клетки вокруг себя, нанося <HighLight>288%</> урона от атаки. Скорость атаки увеличивается на <HighLight>30%</>, эффект длится <HighLight>4</> сек.",
    ["以裹挟潮水的重拳攻击<HighLight>1</>格内当前目标，造成<HighLight>100%攻击伤害</>。"] = "Тяжёлым ударом, несущим прилив, атакует текущую цель в радиусе <HighLight>1</> клетки, нанося <HighLight>100% урона от атаки</>.",
    ["以闪电射线连续贯穿前方敌人，并在目标区域引爆，全部命中共造成{*d,F1690001,atkMin,7.3}点攻击伤害。三星时：以闪电射线连续贯穿前方敌人，并在目标区域引爆，全部命中共造成{*d,F1690001,atkMin,15}点攻击伤害。"] = "Раз за разом пронзает врагов впереди молниями и взрывает их в целевой области; при всех попаданиях наносит в сумме {*d,F1690001,atkMin,7.3} ед. урона от атаки. 3 звезды: при всех попаданиях наносит в сумме {*d,F1690001,atkMin,15} ед. урона от атаки.",
    ["伤害周围敌人并创建死亡领域，领域逐层扩张并处决残血敌人。"] = "Наносит урон окружающим врагам и создаёт домен смерти, который расширяется слой за слоем и казнит врагов с малым запасом здоровья.",
    ["伤害周围敌人，并随机获得护盾或伤害减免。"] = "Ранит окружающих врагов и случайно получает щит или снижение урона.",
    ["伤害测试技能"] = "Навык проверки урона",
    ["伸头一锤"] = "Удар молотом",
    ["伸头重击，近身撞击当前目标。"] = "Вытягивает голову для мощного удара, врезаясь в текущую цель в ближнем бою.",
    ["位移至预选落点，对落点周围1格敌人造成150%攻击伤害"] = "Перемещение в выбранную точку приземления, нанося 150% урона атаки врагам в радиусе 1 клетки",
    ["位移至预选落点，对落点周围<HighLight>1</>格内的敌人造成<HighLight>150%</>攻击伤害。"] = "Перемещение в выбранную точку приземления, нанося <HighLight>150%</> урона атаки врагам в радиусе <HighLight>1</> клетки от неё.",
    ["使用<HighLight>窃影相机</>，寻找一件合适的物体进行拍摄，得到该物体的窃影，用于置换所在事件内另一件同形状物体，阻止人物的死亡。"] = "Используйте <HighLight>Теневую камеру</>, чтобы найти подходящий предмет и сфотографировать его. Полученная тень предмета позволит заменить другой предмет такой же формы в этом событии и не дать персонажу погибнуть.",
    ["使用后可以短暂进入空间的另一形态。"] = "После использования позволяет ненадолго войти в иную форму пространства.",
    ["使用手杖，进入半冥想状态，感知身体和心灵的变化，从而准确找到目标物体或人的位置。"] = "Опираясь на трость, войти в состояние полумедитации и почувствовать изменения в теле и разуме, чтобы точно определить местонахождение искомого предмета или человека.",
    ["使用护符的能力展开护盾，庇护自己和伙伴们。"] = "Использует силу оберега, разворачивая щит для защиты себя и соратников.",
    ["使用相机"] = "Использовать камеру",
    ["倒吊人浪击"] = "Волновой удар Повешенного",
    ["倒吊人雷击"] = "Удар молнии Повешенного",
    ["先轰击前方较小的矩形区域，造成{*d,F1690001,atkMin,2}点攻击伤害。随后对目标及其周围<HighLight>1</>格内的敌人造成{*d,F1690001,atkMin,0.95}点攻击伤害，并使其眩晕<HighLight>1</>秒。最后轰击前方更大的矩形区域，造成{*d,F1690001,atkMin,2}点攻击伤害。"] = "Сначала обстреливает небольшую прямоугольную область впереди, нанося {*d,F1690001,atkMin,2} ед. урона от атаки. Затем наносит цели и врагам в пределах <HighLight>1</> клетки от неё {*d,F1690001,atkMin,0.95} ед. урона от атаки и оглушает их на <HighLight>1</> сек. Наконец обстреливает большую прямоугольную область впереди, нанося {*d,F1690001,atkMin,2} ед. урона от атаки.",
    ["入梦"] = "Погружение в сон",
    ["冲击"] = "Удар",
    ["冲向目标并引发地面冲击，对主目标造成{*d,F1690001,atkMin,3.4}点攻击伤害，对周围敌人造成{*d,F1690001,atkMin,1.8}点攻击伤害并使其眩晕<HighLight>1</>秒。"] = "Врывается к цели и раскалывает землю: наносит основной цели {*d,F1690001,atkMin,3.4} ед. урона от атаки, а окружающим врагам — {*d,F1690001,atkMin,1.8} ед. и оглушает их на <HighLight>1</> сек.",
    ["凝聚知识冲击，远程攻击当前目标。"] = "Концентрирует удар знания, атакуя текущую цель на расстоянии.",
    ["击打"] = "Удар",
    ["切换视角"] = "Переключить ракурс",
    ["切换视角观察现在所处的位置"] = "Переключить ракурс для осмотра текущего местоположения.",
    ["刺击"] = "Колющий удар",
