    ["剑刃风暴"] = "Вихрь клинков",
    ["剑刃风暴免控并获得伤害减免，结束后恢复生命。"] = "Буря клинков даёт иммунитет к контролю и снижение урона, после неё восстанавливает здоровье.",
    ["千钧劈"] = "Сокрушительный раскол",
    ["午夜诗篇"] = "Полуночная поэма",
    ["午夜诗篇伤害并安眠敌人，同时提高自身攻速。"] = "«Полуночный псалом» наносит урон и усыпляет врагов, одновременно повышая собственную скорость атаки.",
    ["单体伤害"] = "Урон по одной цели",
    ["卜杖寻路"] = "Поиск пути лозоходством.",
    ["占卜"] = "Гадание",
    ["卷起浪击，近身攻击当前目标。"] = "Поднимает волну, атакуя текущую цель в ближнем бою.",
    ["厄运之牌"] = "Карта Несчастья",
    ["原初黑焰"] = "Изначальное чёрное пламя",
    ["厨刀劈砍"] = "Удар кухонным ножом",
    ["友善"] = "Дружелюбный",
    ["双牌贯穿前方，同时强化攻击与攻速。"] = "Две карты пронзают врагов впереди и одновременно усиливают атаку и скорость атаки.",
    ["发出三次死灵怒嚎，震击周围敌人，共造成{*d,F1690001,atkMin,1.25}点攻击伤害，自身获得{*d,F1690001,maxHp,0.4}点护盾，持续<HighLight>5</>秒。三星时：发出三次死灵怒嚎，震击周围敌人，共造成{*d,F1690001,atkMin,3.4}点攻击伤害，自身获得{*d,F1690001,maxHp,0.4}点护盾，持续<HighLight>5</>秒。"] = "Трижды издаёт некротический вой, сотрясая окружающих врагов и нанося в сумме {*d,F1690001,atkMin,1.25} ед. урона от атаки. Получает щит на {*d,F1690001,maxHp,0.4} ед. на <HighLight>5</> сек. 3 звезды: в сумме {*d,F1690001,atkMin,3.4} ед. урона от атаки и щит на {*d,F1690001,maxHp,0.4} ед. на <HighLight>5</> сек.",
    ["发出刺耳的警笛声。"] = "Издает пронзительный вой сирены.",
    ["发出四次狼嚎冲击前方，共造成{*d,F1690001,atkMin,2.46}点攻击伤害。自身每损失<HighLight>10%</>最大生命，获得<HighLight>3%</>攻速和吸血，至多<HighLight>30%</>，生命恢复时重新计算。"] = "Издаёт вперёд четыре волчьих воя, в сумме {*d,F1690001,atkMin,2.46} ед. урона от атаки. За каждые потерянные <HighLight>10%</> макс. здоровья получает <HighLight>3%</> скорости атаки и вампиризма (не более <HighLight>30%</>); при восстановлении здоровья бонус пересчитывается.",
    ["发出清脆的车铃声。"] = "Издаёт звонкий перезвон колокольчика.",
    ["发出游戏邀请，远程攻击当前目标。"] = "Отправляет игровое приглашение, атакуя текущую цель на расстоянии.",
    ["发出短促的鸣笛声。"] = "Издаёт короткий гудок.",
    ["发动六段剑刃风暴，共造成{*d,F1690001,atkMin,2.7}点攻击伤害。施法期间免疫控制并获得<HighLight>10%</>伤害减免，持续<HighLight>4</>秒。结束时恢复自身{*d,F1690001,maxHp,0.05}、{*d,F1690001,maxHp,0.1}或{*d,F1690001,maxHp,0.15}点生命，自身生命比例越低，治疗量越高。"] = "Обрушивает вихрь клинков из шести ударов, в сумме {*d,F1690001,atkMin,2.7} ед. урона от атаки. Во время применения невосприимчив к контролю и получает <HighLight>10%</> снижения урона на <HighLight>4</> сек. По завершении восстанавливает {*d,F1690001,maxHp,0.05}, {*d,F1690001,maxHp,0.1} или {*d,F1690001,maxHp,0.15} ед. здоровья: чем ниже доля здоровья, тем сильнее исцеление.",
    ["发动星界力量，穿梭环绕对身前敌人造成伤害并附加减疗。"] = "Взывает к силе Астрального мира, стремительно кружа вокруг врагов перед собой, нанося урон и снижая их исцеление.",
    ["发射三枚飞弹，连续攻击当前目标。"] = "Выпускает три снаряда, непрерывно атакуя текущую цель.",
    ["发射两枚机械眼弹，各造成<HighLight>265%</>攻击伤害。"] = "Выпускает два механических глаза-снаряда, каждый наносит <HighLight>265%</> урона от атаки.",
    ["发射孢子弹，远程攻击当前目标。"] = "Выпускает споровый снаряд, атакуя текущую цель на расстоянии.",
    ["发射星辉弹，对<HighLight>4</>格内当前目标造成<HighLight>100%攻击伤害</>。"] = "Выпускает снаряд звёздного сияния, нанося текущей цели в пределах <HighLight>4</> клеток <HighLight>100% урона от атаки</>.",
    ["发射星辉弹，远程攻击当前目标。"] = "Выпускает снаряд звёздного сияния, атакуя текущую цель на расстоянии.",
    ["发射炮弹，可对建筑造成高额伤害。"] = "Выпускает пушечное ядро, наносящее строениям высокий урон.",
    ["发射知识弹，远程攻击当前目标。"] = "Выпускает снаряд знания, атакуя текущую цель на расстоянии.",
    ["发射窥秘射击，远程攻击当前目标。"] = "Производит скрытный выстрел, атакуя текущую цель на расстоянии.",
    ["发射蔓花毒刺，远程攻击当前目标。"] = "Выпускает ядовитый шип лозы, атакуя текущую цель на расстоянии.",
    ["发射连环炮弹，可对建筑造成高额伤害。"] = "Выпускает серию снарядов, наносящих высокий урон постройкам.",
    ["发射魅影能量弹，远程攻击当前目标。"] = "Выпускает энергетический снаряд-фантом, атакует текущую цель на расстоянии.",
    ["发射齿轮光束，远程攻击当前目标。"] = "Выпускает шестерёнчатый луч, атакуя текущую цель издалека.",
    ["召唤多枚能量弹，连续追击当前目标。"] = "Призывает несколько энергетических снарядов, которые непрерывно преследуют текущую цель.",
    ["召唤星之虫幻化为的秘偶来释放奇迹牌雨，对目标4.5米范围内敌方造成spellfielddisc(*id)点伤害，同时以*f**的基础概率<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>范围中心的敌方0.8秒，最多<HighLight>眩晕</>2人。"] = "Призывает марионетку, созданную из Звёздного червя, для обрушения ливня Карт Чудес, нанося врагам в радиусе 4,5 м от цели spellfielddisc(*id) ед. урона и с базовой вероятностью *f** накладывая <HyperLink stylename=\"M_Link\" u=\"6\">оглушение</> на врагов в центре зоны на 0,8 сек. (максимум <HighLight>оглушает</> 2 цели).",
    ["召唤星之虫幻化为的秘偶释放奇迹牌雨，对目标范围内敌方造成伤害，同时眩晕范围中心的敌方。"] = "Призывает марионетку, созданную из Звёздного червя, обрушивающую Дождь Чудесных Карт: наносит урон врагам в целевой области и оглушает врагов в её центре.",
    ["召唤星光囚笼对目标造成伤害和眩晕。"] = "Призывает Звёздную Клетку, наносящую урон цели и оглушающую её.",
    ["召唤星光囚笼对锁定目标造成{CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d}点魔法伤害和<HighLight>100%</>基础概率的<HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?1}{CheckStar(Type=\"sealed\",ID=2085019)=2?1.25}{CheckStar(Type=\"sealed\",ID=2085019)=3?1.5}</>秒<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>。"] = "Призовите клетку звездного света, чтобы нанести маг. урона {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} заблокированной цели и применить <HighLight> 100% базовый шанс </> на <HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?1}{CheckStar(Type=\"sealed\",ID=2085019)=2?1.25}{CheckStar(Type=\"sealed\",ID=2085019)=3?1.5}</> оглушения на <HyperLink stylename=\"M_Link\" u=\"6\"> сек.</>.",
    ["召唤暴走齿轮轰击前方敌人。"] = "Призывает бешеную шестерню, обстреливающую врагов впереди.",
    ["召唤诡秘之境的历史投影，操纵目标敌人的灵体之线，滞涩范围内敌人，对范围内敌人持续造成伤害，随后终结一击造成大量伤害并击飞怪物目标，眩晕玩家目标。"] = "Призывает историческую проекцию Царства Тайн, управляя нитями духовного тела выбранных врагов: накладывает тягучесть на врагов в области действия, непрерывно нанося им урон, после чего наносит завершающий удар с огромным уроном, подбрасывая монстров и оглушая игроков.",
    ["可在空中飞行。"] = "Позволяет летать по воздуху.",
    ["可在邓恩和戴莉之间切换主导角色"] = "Позволяет переключать основного персонажа между Данном и Дейли.",
    ["可让车辆座驾在空中短暂行驶。"] = "Позволяет транспорту ненадолго перемещаться по воздуху.",
    ["可骑乘龙背，在<HighLight>大世界和GVG战场</>飞行。\n\n驰骋于战场之上，俯瞰脚下众生。"] = "Позволяет летать верхом на драконе в <HighLight>большом мире и на полях сражений GVG</>.\n\nМчитесь над полем брани, взирая на копошащихся внизу смертных с высоты.",
    ["同乘"] = "Совместная поездка.",
    ["同时锁定多名敌人，以拘捕令重创并拉至身前。"] = "Захватывает сразу нескольких врагов, наносит тяжёлый урон ордером на арест и подтягивает их к вам.",
    ["吐息"] = "Дыхание",
    ["向<HighLight>2</>格内当前目标投射暗影弹，造成<HighLight>100%攻击伤害</>。"] = "Выпускает снаряд тени по текущей цели в пределах <HighLight>2</> клеток, нанося <HighLight>100% урона от атаки</>.",
    ["向<HighLight>2</>格内当前目标投递账单，造成<HighLight>115%攻击伤害</>。"] = "Доставляет счёт текущей цели в пределах <HighLight>2</> клеток, нанося <HighLight>115% урона от атаки</>.",
    ["向先祖铠甲扔出绊索，使其移动速度大幅降低。"] = "Бросает под ноги Доспехам предка растяжку, значительно снижая их скорость передвижения.",
    ["向前方释放两次音波冲击，共造成{*d,F1690001,atkMin,2.84}点攻击伤害，自身及附近<HighLight>2</>格内友军获得{*d,F1690001,maxHp,0.07}点护盾，持续<HighLight>4</>秒。三星时：向前方释放两次音波冲击，共造成{*d,F1690001,atkMin,6.52}点攻击伤害，自身及附近<HighLight>2</>格内友军获得{*d,F1690001,maxHp,0.07}点护盾，持续<HighLight>4</>秒。"] = "Выпускает вперёд два звуковых импульса, наносящих в сумме {*d,F1690001,atkMin,2.84} ед. урона от атаки, и даёт себе и союзникам в радиусе <HighLight>2</> клеток {*d,F1690001,maxHp,0.07} ед. щита на <HighLight>4</> сек. При 3 звёздах: выпускает вперёд два звуковых импульса, наносящих в сумме {*d,F1690001,atkMin,6.52} ед. урона от атаки, и даёт себе и союзникам в радиусе <HighLight>2</> клеток {*d,F1690001,maxHp,0.07} ед. щита на <HighLight>4</> сек.",
    ["向前重踏并伤害敌人。"] = "Делает мощный шаг вперёд, нанося урон врагам.",
    ["向前重踏，伤害并击退敌人，同时获得伤害减免。"] = "Тяжело топает вперёд, нанося урон и отбрасывая врагов, и получает снижение урона.",
    ["向当前目标发射<HighLight>3</>枚飞弹，共造成<HighLight>100%攻击伤害</>。"] = "Выпускает по текущей цели <HighLight>3</> снаряда, в сумме нанося <HighLight>100% урона от атаки</>.",
    ["向目标区域释放三重怨念脉冲。"] = "Высвобождает в целевой области тройной импульс злобы.",
    ["向目标区域释放三重怨念，共造成{*d,F1690001,atkMin,4.6}点攻击伤害。三星时：向目标区域释放三重怨念，共造成{*d,F1690001,atkMin,9.6}点攻击伤害。"] = "Высвобождает в целевую область тройную обиду, нанося в сумме {*d,F1690001,atkMin,4.6} ед. урона от атаки. 3 звезды: в сумме {*d,F1690001,atkMin,9.6} ед. урона от атаки.",
    ["吞咬护佑"] = "Защита пожирателя",
    ["吞咬目标，造成{*d,F1690001,atkMin,3.33}点攻击伤害，并为己方全体提供护盾，护盾值为各自最大生命的<HighLight>15%</>，持续<HighLight>5</>秒。"] = "Кусает цель, нанося {*d,F1690001,atkMin,3.33} ед. урона от атаки, и даёт всем союзникам щит на <HighLight>15%</> их макс. здоровья на <HighLight>5</> сек.",
    ["吞咬重创目标，并为己方全体提供护盾。"] = "Укусом тяжело ранит цель и даёт щит всем союзникам.",
    ["吟诵午夜诗篇，对周围敌人造成{*d,F1690001,atkMin,1.93}点攻击伤害并使其安眠<HighLight>1</>秒，自身攻速提高<HighLight>15%</>，持续<HighLight>4</>秒。三星时：吟诵午夜诗篇，对周围敌人造成{*d,F1690001,atkMin,5.4}点攻击伤害并使其安眠<HighLight>1</>秒，自身攻速提高<HighLight>15%</>，持续<HighLight>4</>秒。"] = "Читает полуночный стих, нанося окружающим врагам {*d,F1690001,atkMin,1.93} ед. урона от атаки и погружая их в Сон на <HighLight>1</> сек.; скорость атаки фигуры повышается на <HighLight>15%</> на <HighLight>4</> сек. 3 звезды: наносит {*d,F1690001,atkMin,5.4} ед. урона от атаки, погружает в Сон на <HighLight>1</> сек.; скорость атаки повышается на <HighLight>15%</> на <HighLight>4</> сек.",
    ["吟诵诗篇回响，远程攻击当前目标。"] = "Читает отголосок псалма, атакуя текущую цель на расстоянии.",
    ["哀恸震击"] = "Скорбное сотрясение",
    ["囚禁"] = "Заточение",
    ["回复药"] = "Зелье восстановления",
    ["回溯"] = "Откат",
    ["圣光"] = "Священный свет",
    ["圣光回响"] = "Эхо Священного Света",
    ["圣光疗愈"] = "Исцеление Священным Светом",
    ["在周围生成6个陷阱，2秒后爆炸，击飞敌人并造成20%最大生命值伤害。"] = "Создаёт 6 ловушек вокруг, которые взрываются через 2 сек., подбрасывая врагов и нанося урон в размере 20% от их максимального здоровья.",
    ["在当前位置留下时间印记"] = "Оставить временную метку в текущей позиции",
    ["在指定位置立下太阳誓约，誓约范围内的敌人受到伤害、滞涩和禁锢效果。"] = "Устанавливает Солнечную Клятву в указанной точке: враги в зоне действия получают урон, а также эффекты тягучести и заточения.",
    ["在指定位置立下持续8秒的太阳誓约，对范围内敌方造成8次{CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d}点物理伤害和持续<HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>。誓约范围内敌方trapdisc(*id)（触发次数存在上限）。"] = "Совершите солнечную клятву, действующую в течение 8 секунд в указанном месте, нанеся 8 {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} очков физического урона и продолжительную <HyperLink stylename=\"M_Link\" u=\"9\">stagnation</> врагам в радиусе действия. Враги в радиусе клятвы подвергаются trapdisc(*id) (есть ограничение на количество срабатываний).",
    ["在敌人密集处引爆蘑菇，造成{*d,F1690001,atkMin,2.43}点攻击伤害，并留下<HighLight>4</>秒菌丝地面。区域内敌人每秒受到{*d,F1690001,atkMin,0.6}点攻击伤害，攻速和移动速度降低<HighLight>20%</>。"] = "Взрывает грибы там, где врагов больше всего, нанося {*d,F1690001,atkMin,2.43} ед. урона от атаки и оставляя на <HighLight>4</> сек. грибницу. Враги в ней получают {*d,F1690001,atkMin,0.6} ед. урона от атаки в секунду, их скорость атаки и передвижения снижена на <HighLight>20%</>.",
    ["在敌人密集处接连绽放三圈藤棘，共造成{*d,F1690001,atkMin,2.3}点攻击伤害，并使敌人攻击降低<HighLight>5%</>，持续<HighLight>4</>秒。"] = "Там, где врагов больше всего, раз за разом распускаются три кольца колючих лоз, нанося в сумме {*d,F1690001,atkMin,2.3} ед. урона от атаки и снижая атаку врагов на <HighLight>5%</> на <HighLight>4</> сек.",
    ["在敌人密集处由外向内引爆三环蔓袭，三环全中共造成{*d,F1690001,atkMin,2.6}点攻击伤害，内圈使命中的敌人眩晕<HighLight>1</>秒。"] = "Там, где врагов больше всего, снаружи внутрь взрываются три кольца лоз; при попадании всех трёх наносит в сумме {*d,F1690001,atkMin,2.6} ед. урона от атаки. Внутреннее кольцо оглушает задетых врагов на <HighLight>1</> сек.",
    ["在敌人密集处绽放三圈藤棘，造成范围伤害并降低敌人攻击。"] = "Выпускает три кольца шипастых лоз в месте скопления врагов, нанося урон по области и снижая атаку врагов.",
    ["在目标位置依次绽放三圈藤棘，合计造成<HighLight>3000%</>攻击伤害。命中的敌人攻击降低<HighLight>5%</>，持续<HighLight>4</>秒。"] = "Последовательно выпускает в целевой точке три кольца шипастых лоз, нанося в сумме <HighLight>3000%</> урона от атаки. Пораженные враги теряют <HighLight>5%</> атаки на <HighLight>4</> сек.",
    ["在目标周围展开诡秘之境，使范围内敌方<HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>*f秒，期间造成6次spellfielddisc(*id)点物理伤害；随后终结一击造成spellfielddisc(*id)点物理伤害，若目标为怪物则<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>目标，若目标为玩家则有概率<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>目标*f秒。"] = "Разворачивает вокруг цели царство тайн, накладывая на врагов в области эффект <HyperLink stylename=\"M_Link\" u=\"9\">Скованность</> на *f сек. За это время наносит 6 ударов по spellfielddisc(*id) ед. физического урона. После этого завершающий удар наносит spellfielddisc(*id) ед. физического урона: если цель — монстр, то <HyperLink stylename=\"M_Link\" u=\"2\">подбрасывает</> её в воздух, а если игрок — с некоторой вероятностью вызывает <HyperLink stylename=\"M_Link\" u=\"6\">Оглушение</> цели на *f сек.",
    ["地面冲击"] = "Удар по земле",
    ["壁垒护身，随后伤敌并治疗友军。"] = "Защищает себя бастионом, затем ранит врагов и лечит союзников.",
    ["多圈藤棘伤害敌人并降低敌人攻击。"] = "Несколько колец шипастых лоз ранят врагов и снижают их атаку.",
    ["太阳誓约"] = "Солнечная клятва",
    ["奇迹庇护"] = "Защита чуда",
    ["奇迹牌雨"] = "Дождь чудесных карт",
    ["奇迹牌雨轰击目标区域。"] = "Дождь Карт чудес обрушивается на целевую область.",
    ["奇迹飞牌"] = "Чудо-карта",
    ["奋力挥出铁壁，清理前方的障碍物。"] = "С силой взмахните «Железной стеной», чтобы расчистить препятствия впереди.",
    ["奏响通灵三重奏，连续冲击周围敌人三次，共造成{*d,F1690001,atkMin,5.33}点攻击伤害。"] = "Играет медиумическое трио, трижды подряд ударяя по окружающим врагам, в сумме {*d,F1690001,atkMin,5.33} ед. урона от атаки.",
    ["好戏开场"] = "Представление начинается",
    ["威压"] = "Давление",
    ["孢子弹"] = "Споровая пуля",
    ["守护"] = "Защита",
    ["守护庇护"] = "Защитный покров",
    ["安抚饼干"] = "Умиротворяющее печенье",
    ["宣判最远敌人，造成<HighLight>733%</>攻击伤害并眩晕<HighLight>1</>秒，使其法力恢复降低<HighLight>8</>点，持续<HighLight>3</>秒。"] = "Выносит приговор самому дальнему врагу, наносит <HighLight>733%</> урона от атаки и оглушает на <HighLight>1</> сек., снижая восстановление маны на <HighLight>8</> ед. в течение <HighLight>3</> сек.",
    ["宣判最远敌人，造成伤害、眩晕并抑制法力恢复。"] = "Выносит приговор самому дальнему врагу, нанося урон, оглушая его и подавляя восстановление маны.",
    ["家庭预算"] = "Семейный бюджет",
    ["对<HighLight>1</>格内当前目标造成<HighLight>100%攻击伤害</>。"] = "Наносит текущей цели в пределах <HighLight>1</> клетки <HighLight>100% урона от атаки</>.",
    ["对<HighLight>1</>格内当前目标造成<HighLight>34%攻击伤害</>。"] = "Наносит текущей цели в радиусе <HighLight>1</> клетки <HighLight>34% урона от атаки</>.",
    ["对<HighLight>2</>格内当前目标造成<HighLight>100%攻击伤害</>。"] = "Наносит текущей цели в пределах <HighLight>2</> клеток <HighLight>100% урона от атаки</>.",
    ["对<HighLight>3</>格内当前目标发射齿轮光束，造成<HighLight>365%</>攻击伤害。"] = "Выпускает шестерёнчатый луч в текущую цель в пределах <HighLight>3</> клеток, нанося <HighLight>365%</> урона от атаки.",
    ["对<HighLight>3</>格内当前目标进行手枪射击，造成<HighLight>100%攻击伤害</>。"] = "Производит выстрел из пистолета по текущей цели в пределах <HighLight>3</> клеток, нанося <HighLight>100% урона от атаки</>.",
    ["对周围敌人打出怒潮三击，末段引爆雷潮击飞敌人并获得护盾。"] = "Наносит окружающим врагам три удара ярости прилива, в конце вызывая взрыв грозового прилива, который отбрасывает врагов, и получает щит.",
    ["对周围敌人造成<HighLight>127%</>攻击伤害。"] = "Наносит находящимся вокруг врагам <HighLight>127%</> урона от атаки.",
    ["对周围敌人造成<HighLight>3000%</>攻击伤害。首次施法创建死亡领域，每次施法使领域提升<HighLight>1</>层，最多<HighLight>3</>层。领域范围为<HighLight>3/4/5</>格，持续处决生命低于<HighLight>25%/50%/100%</>的敌人。"] = "Наносит окружающим врагам <HighLight>3000%</> урона атаки. Первое применение создаёт область смерти, каждое применение повышает её на <HighLight>1</> уровень, максимум <HighLight>3</> уровня. Радиус области: <HighLight>3/4/5</> клетки; она непрерывно казнит врагов со здоровьем ниже <HighLight>25%/50%/100%</>.",
    ["对周围敌人造成{*d,F1690001,atkMin,1}点攻击伤害，并随机获得<HighLight>20%</>最大生命护盾或<HighLight>30%</>伤害减免，持续<HighLight>5</>秒。"] = "Наносит окружающим врагам {*d,F1690001,atkMin,1} ед. урона от атаки и случайно получает щит на <HighLight>20%</> макс. здоровья или <HighLight>30%</> снижения урона на <HighLight>5</> сек.",
    ["对周围造成<HighLight>160%</>攻击伤害。生命不高于<HighLight>35%</>的敌人额外受到<HighLight>80%</>攻击伤害。命中敌人防御降低<HighLight>20%</>，持续<HighLight>4</>秒。"] = "Наносит окружающим <HighLight>160%</> урона атаки. Враги со здоровьем не выше <HighLight>35%</> получают дополнительно <HighLight>80%</> урона атаки. Пораженные враги теряют <HighLight>20%</> защиты на <HighLight>4</> сек.",
    ["对当前目标及其<HighLight>1</>格范围敌人造成<HighLight>51%攻击伤害</>。"] = "Наносит <HighLight>51% урона от атаки</> текущей цели и врагам в радиусе <HighLight>1</> клетки.",
    ["对当前目标造成<HighLight>100%攻击伤害</>。"] = "Наносит текущей цели <HighLight>100%</> урона от атаки.",
    ["对当前目标造成<HighLight>536%</>攻击伤害。"] = "Наносит текущей цели <HighLight>536%</> урона от атаки.",
    ["对当前目标造成<HighLight>90%</>攻击伤害。"] = "Наносит текущей цели <HighLight>90%</> урона от атаки.",
    ["对目标区域造成<HighLight>502%</>攻击伤害。"] = "Наносит <HighLight>502%</> урона от атаки по целевой области.",
    ["对目标进行积极的心理暗示，立刻为目标回复大量生命值，并为其提供短暂的减伤效果。"] = "Применяет к цели позитивное психологическое внушение, мгновенно восстанавливая ей значительное количество здоровья и даруя кратковременное Снижение урона.",
    ["对自身周围<HighLight>1</>格内的敌人打出三段重拳，分别造成<HighLight>44.33%/44.33%/44.34%</>攻击伤害。最后一击击飞敌人<HighLight>0.6</>秒，自身获得<HighLight>25%</>最大生命护盾，持续<HighLight>4</>秒。"] = "Наносит врагам в радиусе <HighLight>1</> клетки вокруг себя три тяжёлых удара, каждый из которых наносит <HighLight>44.33%/44.33%/44.34%</> урона от атаки. Последний удар подбрасывает врагов на <HighLight>0.6</> сек., а сам персонаж получает щит в размере <HighLight>25%</> максимального здоровья на <HighLight>4</> сек.",
    ["对自身周围<HighLight>2</>格内的敌人造成{*d,F1690001,atkMin,1.93}点攻击伤害。自身获得<HighLight>20%</>伤害减免，持续<HighLight>4</>秒。"] = "Наносит врагам в пределах <HighLight>2</> клеток вокруг себя {*d,F1690001,atkMin,1.93} ед. урона от атаки. Получает <HighLight>20%</> снижения урона на <HighLight>4</> сек.",
    ["对身前圆形范围内敌方造成{CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d}点魔法伤害，并附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。"] = "Нанесите {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} магического урона врагам в круговой области перед вами и примените <HyperLink stylename=\"M_Link\" u=\"20\">Снижение лечения</> на *f сек., уменьшая лечение на mul(*d**,*d).",
    ["射出星辉贯穿箭，对直线上的敌人造成{*d,F1690001,atkMin,2.9025}点攻击伤害，并在目标位置引爆，造成{*d,F1690001,atkMin,0.9675}点范围伤害。"] = "Выпускает пронзающую стрелу звёздного сияния, нанося врагам на линии {*d,F1690001,atkMin,2.9025} ед. урона от атаки, а в точке цели стрела взрывается и наносит {*d,F1690001,atkMin,0.9675} ед. урона по области.",
    ["将污秽果实投向失智者，通过污秽之力对冲其无敌效果"] = "Бросьте оскверненный плод в обезумевшего, чтобы силой скверны нейтрализовать его неуязвимость",
