    ["挥爪撕裂，近身攻击当前目标。"] = "Взмах когтями разрывает цель, атака ближнего боя по текущей цели.",
    ["挥爪连续撕裂当前目标。"] = "Наносит текущей цели серию рвущих ударов когтями.",
    ["挥镰斩击目标，造成{*d,F1690001,atkMin,1.8}点攻击伤害，目标生命不高于<HighLight>35%</>时提高至{*d,F1690001,atkMin,2.7}点攻击伤害。随后留下<HighLight>4</>秒花域，使敌人每秒受到{*d,F1690001,atkMin,0.2}点攻击伤害，攻速和移动速度降低<HighLight>20%</>。"] = "Рассекает цель косой, нанося {*d,F1690001,atkMin,1.8} ед. урона от атаки (если здоровье цели не выше <HighLight>35%</> — {*d,F1690001,atkMin,2.7}). Затем оставляет на <HighLight>4</> сек. цветочное поле: враги в нём получают {*d,F1690001,atkMin,0.2} ед. урона от атаки в секунду, их скорость атаки и передвижения снижена на <HighLight>20%</>.",
    ["挥镰造成<HighLight>180%</>攻击伤害。生命不高于<HighLight>35%</>的敌人额外受到<HighLight>90%</>攻击伤害。"] = "Взмах косой наносит <HighLight>180%</> урона от атаки. Враги со здоровьем не выше <HighLight>35%</> получают дополнительно <HighLight>90%</> урона от атаки.",
    ["挥镰重创残血目标，花域持续伤害并减速。"] = "Взмахом косы тяжело ранит цели с низким здоровьем; цветочное поле наносит постоянный урон и замедляет.",
    ["振翼爆发，对周围敌人造成<HighLight>150%</>攻击伤害。"] = "Взмахом крыльев производит взрыв, нанося окружающим врагам <HighLight>150%</> урона от атаки.",
    ["振翼爆发，对周围敌人造成伤害。"] = "Взмахом крыльев производит взрыв, нанося урон окружающим врагам.",
    ["掀起浪墙横扫前方，造成{*d,F1690001,atkMin,2.7733}点攻击伤害并击退敌人。随后落雷轰击同一区域，追加{*d,F1690001,atkMin,1.3867}点攻击伤害。"] = "Поднимает стену волн и сметает всё впереди, нанося {*d,F1690001,atkMin,2.7733} ед. урона от атаки и отбрасывая врагов. Затем в ту же область бьёт молния, нанося ещё {*d,F1690001,atkMin,1.3867} ед. урона от атаки.",
    ["接连轰击前方与目标周围，第二段使敌人眩晕。"] = "Обстреливает по очереди область впереди и вокруг цели; второй залп оглушает врагов.",
    ["控制警灯开关。"] = "Переключатель проблескового маячка.",
    ["控制警灯的打开和关闭。"] = "Управление включением и выключением проблескового маячка.",
    ["控制车灯开关。"] = "Переключатель фар.",
    ["控制车辆车头大灯的打开和关闭。"] = "Управляйте включением и выключением фар автомобиля.",
    ["掷出两张末日纸牌，贯穿前方敌人，共造成{*d,F1690001,atkMin,2.6}点攻击伤害。随后提高<HighLight>20%</>攻速和<HighLight>15%</>攻击，持续<HighLight>4</>秒。"] = "Бросает две карты Судного дня, пронзающие врагов впереди, в сумме {*d,F1690001,atkMin,2.6} ед. урона от атаки. Затем повышает скорость атаки на <HighLight>20%</> и атаку на <HighLight>15%</> на <HighLight>4</> сек.",
    ["掷出奇迹飞牌，远程攻击当前目标。"] = "Бросает летающую карту чуда, атакуя текущую цель на расстоянии.",
    ["掷出纸牌飞刀，远程攻击当前目标。"] = "Метает бумажные карты-ножи, атакует текущую цель на расстоянии.",
    ["提升灵性之跃能力，可在空中悬停。"] = "Усиливает способность «Прыжок духовности», позволяя зависать в воздухе.",
    ["撕裂"] = "Разрыв",
    ["收音机"] = "Радиоприемник",
    ["攻击当前目标<HighLight>1</>次，造成<HighLight>100%</>攻击伤害。"] = "Атакует текущую цель <HighLight>1</> раз, нанося <HighLight>100%</> урона от атаки.",
    ["攻击目标，造成{*d,F1690001,atkMin,3}点攻击伤害。目标生命不高于<HighLight>35%</>时，改为{*d,F1690001,atkMin,4}点攻击伤害。自身吸血提高<HighLight>30%</>，持续<HighLight>3</>秒。三星时：攻击目标，造成{*d,F1690001,atkMin,7}点攻击伤害。目标生命不高于<HighLight>35%</>时，改为{*d,F1690001,atkMin,10}点攻击伤害。自身吸血提高<HighLight>30%</>，持续<HighLight>3</>秒。"] = "Атакует цель, нанося {*d,F1690001,atkMin,3} ед. урона от атаки. Если здоровье цели не выше <HighLight>35%</>, урон меняется на {*d,F1690001,atkMin,4} ед. Собственный вампиризм повышается на <HighLight>30%</> на <HighLight>3</> сек. При 3 звёздах: атакует цель, нанося {*d,F1690001,atkMin,7} ед. урона от атаки. Если здоровье цели не выше <HighLight>35%</>, урон меняется на {*d,F1690001,atkMin,10} ед. Собственный вампиризм повышается на <HighLight>30%</> на <HighLight>3</> сек.",
