    ["绿华"] = "Изумрудное сияние",
    ["群狼号令"] = "Команда волчьей стаи",
    ["老爷车喇叭旧"] = "Старый автомобильный клаксон",
    ["老维克多的怀表能力，可以在空间的“稳定态”与“侵蚀态”间切换。"] = "Способность карманных часов старого Виктора позволяет переключаться между «стабильным» и «эродированным» состояниями пространства.",
    ["能量召唤"] = "Энергетический призыв",
    ["腐烂的流星"] = "Гниющий метеор",
    ["舞动血焰横扫自身周围的全部敌人，并提高自身攻速。"] = "Танец кровавого пламени поражает всех врагов вокруг себя и повышает собственную скорость атаки.",
    ["舞王狒哥旋身震荡周围，对自身<HighLight>2</>格圆形范围内的敌人造成{*d,F1690001,atkMin,1.74}点攻击伤害，并恢复自身<HighLight>30%</>最大生命。"] = "Король танца Бабуин кружится и сотрясает всё вокруг, нанося врагам в круге радиусом <HighLight>2</> клетки {*d,F1690001,atkMin,1.74} ед. урона от атаки, и восстанавливает себе <HighLight>30%</> макс. здоровья.",
    ["苍白的死亡阵亡2格爆发"] = "Pale Dead casualty 2-grid Burst",
    ["荣耀之证"] = "Свидетельство славы",
    ["莫雷蒂家的账本"] = "Бухгалтерская книга семьи Моретти",
    ["获得<HighLight>15%</>最大生命护盾，持续<HighLight>5</>秒。<HighLight>1.2</>秒后对周围造成<HighLight>102%</>攻击伤害，并使附近友军恢复<HighLight>5%</>最大生命。"] = "Получает щит в размере <HighLight>15%</> максимального здоровья на <HighLight>5</> сек. Через <HighLight>1.2</> сек наносит находящимся вокруг <HighLight>102%</> урона от атаки и восстанавливает находящимся поблизости союзникам <HighLight>5%</> максимального здоровья.",
    ["获得<HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?21%}{CheckStar(Type=\"sealed\",ID=2085019)=2?30%}{CheckStar(Type=\"sealed\",ID=2085019)=3?39%}</>最大生命值的护盾，持续*f秒；当护盾被击破时，自身获得buffdisc(*id)秒<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，该效果有buffdisc(*id)秒内置冷却。"] = "Получите щит, равный <HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?21%}{CheckStar(Type=\"sealed\",ID=2085019)=2?30%}{CheckStar(Type=\"sealed\",ID=2085019)=3?39%}</> от вашего максимального здоровья, длительностью *f сек.. Когда щит сломан, вы получаете <HyperLink stylename=\"M_Link\" u=\"11\">Суперброню</> на buffdisc(*id) сек.. Этот эффект имеет внутреннее время восстановления buffdisc(*id) сек..",
    ["获得{*d,F1690001,maxHp,0.3}点护盾，持续<HighLight>5</>秒。<HighLight>1.2</>秒后震击周围敌人，造成{*d,F1690001,atkMin,1.1}点攻击伤害，并为周围友军恢复各自最大生命的<HighLight>8%</>。"] = "Получает щит на {*d,F1690001,maxHp,0.3} ед. на <HighLight>5</> сек. Через <HighLight>1.2</> сек. сотрясает окружающих врагов, нанося {*d,F1690001,atkMin,1.1} ед. урона от атаки, и восстанавливает союзникам вокруг <HighLight>8%</> их макс. здоровья.",
    ["获得增益效果，强化所有战斗技能和终结技，提升其攻击速度，并每秒返还冷却时间。"] = "Дарует усиление, усиливающее все боевые навыки и добивания, повышает их скорость атаки и каждую секунду сокращает время Перезарядки.",
    ["获得如何穿梭混乱与秩序世界，以及如何巧妙搬运大剑的指导。"] = "Получите наставления о том, как перемещаться между мирами Хаоса и Порядка, а также как искусно владеть двуручным мечом.",
    ["获得护盾并震击周围敌人，同时治疗友军。"] = "Получает щит и наносит ударную волну по находящимся вокруг врагам, одновременно исцеляя союзников.",
    ["获得混乱大剑的魔力"] = "Обретите магическую силу Двуручного меча Хаоса.",
    ["获得秩序大剑的魔力"] = "Обретите магическую силу Двуручного меча Порядка.",
    ["蓄力射出贯穿箭，伤害直线敌人，并在目标位置造成范围伤害。"] = "Заряжает и выпускает пронзающую стрелу, наносящую урон врагам по прямой линии, а также урон по области в точке попадания.",
    ["蓄力射击"] = "Заряженный выстрел",
    ["蓄力射击·脱手结算"] = "Заряженный выстрел · Расчёт при выпуске",
    ["蓄力重击，近身攻击当前目标。"] = "Charged Heavy blow, attacking the current target at close range.",
    ["蔓花毒刺"] = "Ядовитое жало цветка лозы",
    ["蔓袭中环"] = "Удар лоз: среднее кольцо",
    ["蔓袭内环"] = "Удар лоз: внутреннее кольцо",
    ["蔓袭外环"] = "Удар лоз: внешнее кольцо",
    ["藤棘绽放"] = "Цветение терновника",
    ["藤蔓横扫"] = "Взмах лоз",
    ["蘑菇农场"] = "Mushroom Farm",
    ["蘑菇爆发"] = "Взрыв грибов",
    ["蘑菇爆炸伤敌，菌丝持续伤害并减速。"] = "Взрыв грибов ранит врагов; грибница наносит постоянный урон и замедляет.",
    ["蘑菇连续爆发三次，造成<HighLight>61.34%/61.34%/210.32%</>攻击伤害。"] = "Гриб взрывается трижды подряд, нанося <HighLight>61.34%/61.34%/210.32%</> урона от атаки.",
    ["蘑菇震荡"] = "Грибное сотрясение",
    ["蛛后猎场"] = "Угодья паучьей королевы",
    ["蠕动的饥饿"] = "Ползучий Голод",
    ["血刃徽章追击"] = "Blood Blade Badge Pursuit",
    ["血影触须"] = "Щупальце кровавой тени",
    ["血月追猎"] = "Охота кровавой луны",
    ["血焰狂舞"] = "Танец кровавого пламени",
    ["血玫绽放"] = "Цветение кровавой розы",
    ["血翼震荡"] = "Взмах кровавых крыльев",
    ["血肉阴影"] = "Тень плоти",
    ["血谋共舞的旗帜"] = "Знамя танца кровавого заговора",
    ["袭击敌人密集区域，造成{*d,F1690001,atkMin,2}点攻击伤害。施法时恢复自身<HighLight>40%</>最大生命，防御提高<HighLight>40</>点，持续<HighLight>4</>秒。"] = "Нападает на скопление врагов, нанося {*d,F1690001,atkMin,2} ед. урона от атаки. При применении восстанавливает <HighLight>40%</> макс. здоровья и повышает защиту на <HighLight>40</> на <HighLight>4</> сек.",
    ["裂地"] = "Раскол земли",
    ["解除自身受到的<HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\">控制效果</>，并在4秒内获得<HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\">霸体</>和50%减伤，将每次受到伤害里不超过生命值上限10%的部分，按{CheckStar(Type=\"sealed\",ID=2085010)=1?0.6}{CheckStar(Type=\"sealed\",ID=2085010)=2?0.75}{CheckStar(Type=\"sealed\",ID=2085010)=3?0.9}倍反弹给攻击者（对8米外的目标，反弹伤害额外衰减，最多衰减至8米内的20%）。\n效果结束时，震碎牢笼，对周身8米内的最多6名敌对目标造成伤害，并对其施加持续10秒的眩目效果，使其攻击降低。"] = "Снимите с себя эффект контроля <HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\"></> и получите <HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\">Суперброню</> и снижение урона на 50% в течение 4 секунд. За каждый полученный урон, не превышающий 10% от верхнего предела здоровья, нажмите {CheckStar(Type=\"sealed\",ID=2085010)=1?0.6}{CheckStar(Type=\"sealed\",ID=2085010)=2?0.75}{CheckStar(Type=\"sealed\",ID=2085010)=3?0.9} раза, отраженного атакующему (для цели 8 метров). вдали урон от отскока будет дополнительно уменьшен до 20% в радиусе 8 метров). \n Когда эффект закончится, клетка разобьется, нанося урон до 6 враждебным целям в радиусе 8 метров и применяя ослепляющий эффект, который длится 10 секунд, чтобы уменьшить их атаку.",
    ["解除自身受到的控制状态，并获得霸体、减伤、反弹伤害效果。效果结束后，对附近敌对目标造成伤害，并对其施加攻击降低效果。"] = "Снимает с себя эффекты контроля, дает Суперброню, снижение входящего урона и отражение урона. По окончании действия наносит урон ближайшим врагам и снижает их силу атаки.",
    ["解除身份置换，回归现实之身"] = "Завершает подмену личности и возвращается в истинное физическое тело.",
    ["警灯"] = "Проблесковый маячок",
    ["记录·牌雨"] = "Запись: Дождь карт",
    ["记录并查看出现过的符文"] = "Записывайте и просматривайте появлявшиеся руны.",
    ["诗篇回响"] = "Эхо поэмы",
    ["诡秘之境"] = "Царство Тайн",
    ["账单投递"] = "Вручение счёта",
    ["贪婪坠击"] = "Алчный сокрушающий удар",
    ["起飞离场"] = "Взлёт",
    ["跃起砸击自身周围敌人，造成<HighLight>215%</>攻击伤害并使其眩晕<HighLight>1</>秒。"] = "Взмывает вверх и обрушивается на окружающих врагов, нанося <HighLight>215%</> урона от атаки и оглушая их на <HighLight>1</> сек.",
    ["跃起裂地砸击周围敌人，并使其眩晕。"] = "Взмывает вверх и обрушивается на землю, поражая окружающих врагов и оглушая их.",
    ["跳砸"] = "Удар в прыжке",
    ["踏着死亡三步曲，近身攻击当前目标。"] = "Исполняет «Танец трёх шагов смерти», атакуя текущую цель в ближнем бою.",
    ["车灯"] = "Фары.",
    ["车载收音机，可收听歌曲。"] = "Автомобильное радио, позволяет слушать музыку.",
    ["转换身份"] = "Смена личности",
    ["轰击目标区域，造成<HighLight>162%</>攻击伤害。治疗生命最低的<HighLight>1</>名友军<HighLight>16%</>最大生命。"] = "Обстреливает целевую область, нанося <HighLight>162%</> урона от атаки. Лечит <HighLight>1</> союзника с наименьшим запасом здоровья на <HighLight>16%</> максимального здоровья.",
    ["过载爆发"] = "Взрыв перегрузки",
    ["近身攻击当前目标一次。"] = "Наносит ближний удар по текущей цели один раз.",
    ["近身狩猎并斩击当前目标。"] = "Атакует текущую цель вблизи и наносит рубящий удар.",
    ["近身连斩"] = "Комбо ближнего боя",
    ["进入霸体并连续挥砍周围敌人。"] = "Входит в состояние суперброни и наносит серию рубящих ударов по окружающим врагам.",
    ["进入霸体，持续<HighLight>4</>秒，并挥砍六次，合计造成<HighLight>256%</>攻击伤害。"] = "Входит в состояние суперброни на <HighLight>4</> сек. и наносит шесть рубящих ударов, суммарно причиняя <HighLight>256%</> урона от атаки.",
    ["连发三枚星辉弹，共造成{*d,F1690001,atkMin,5.37}点攻击伤害。命中后为生命比例最低的友军恢复<HighLight>16%</>最大生命。"] = "Выпускает подряд три снаряда звёздного сияния, в сумме {*d,F1690001,atkMin,5.37} ед. урона от атаки. При попадании восстанавливает <HighLight>16%</> макс. здоровья союзнику с наименьшей долей здоровья.",
    ["连环炮击"] = "Серийная бомбардировка",
    ["连续发射三枚星辉弹，末次命中恢复法力并治疗生命最低的友军。"] = "Выпускает подряд три снаряда звёздного сияния; последнее попадание восстанавливает ману и лечит союзника с наименьшим запасом здоровья.",
    ["连续发射五枚能量弹，每段伤害逐次变化，平均每段造成<HighLight>132%</>攻击伤害，五段合计造成<HighLight>660%</>攻击伤害。"] = "Выпускает подряд пять энергетических снарядов, урон каждого выстрела меняется, в среднем каждый наносит <HighLight>132%</> урона от атаки, суммарно пять выстрелов наносят <HighLight>660%</> урона от атаки.",
    ["连续喷吐九次，每次造成<HighLight>48%</>攻击伤害。命中施加灼烧，每秒损失<HighLight>1%</>最大生命，持续<HighLight>4</>秒。"] = "Изрыгает пламя девять раз подряд, каждый раз нанося <HighLight>48%</> урона от атаки. При попадании накладывает поджог, отнимающий <HighLight>1%</> максимального здоровья в секунду в течение <HighLight>4</> сек.",
    ["连续四次挥动黑镰，斩击前方敌人。"] = "Четыре раза подряд взмахивает чёрной косой, рубя врагов впереди.",
